package gadomancymodern.aura;

import net.minecraft.core.BlockPos;
import net.minecraft.server.level.*;
import net.minecraft.world.effect.*;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.monster.*;
import net.minecraft.world.entity.animal.*;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.*;
import net.minecraft.world.level.block.Blocks;
import tc4revival.content.*;

/** Original author aura rules; effect sampling is deliberately distinct from normal random ticks. */
public class StandardAuraEffects {
    public static void register(){GadEffects.VIS_AFFINITY.get().addAttributeModifier(TCAttributes.VIS_COST.get(),"4d1eeb26-6041-4a3a-bfde-709b66f71f5d",-.08,net.minecraft.world.entity.ai.attributes.AttributeModifier.Operation.ADDITION);
        potion("aer",MobEffects.MOVEMENT_SPEED,4,6,6,1);potion("aqua",MobEffects.WATER_BREATHING,4,10,10,0);potion("terra",MobEffects.DAMAGE_RESISTANCE,4,8,5,0);potion("ordo",MobEffects.REGENERATION,4,6,3,0);potion("perditio",MobEffects.WEAKNESS,4,8,3,0);potion("telum",MobEffects.DAMAGE_BOOST,4,6,6,2);potion("tutamen",MobEffects.DAMAGE_RESISTANCE,4,6,6,1);potion("motus",MobEffects.MOVEMENT_SPEED,4,6,2,2);potion("iter",MobEffects.MOVEMENT_SPEED,2,10,15,0);potion("fames",MobEffects.HUNGER,4,6,2,0);potion("sensus",MobEffects.NIGHT_VISION,2,8,8,0);potion("volatus",MobEffects.JUMP,2,5,4,0);potion("potentia",MobEffects.DAMAGE_BOOST,4,6,4,0);potion("tenebrae",MobEffects.BLINDNESS,4,6,1,0);potion("sano",MobEffects.REGENERATION,8,10,5,1);potion("mortuus",MobEffects.WITHER,4,6,3,1);potion("humanus",MobEffects.HEALTH_BOOST,2,5,4,1);potion("instrumentum",MobEffects.DIG_SPEED,2,7,6,0);potion("perfodio",MobEffects.DIG_SPEED,2,7,5,2);potion("venenum",MobEffects.POISON,2,6,1,0);potion("vinculum",MobEffects.MOVEMENT_SLOWDOWN,4,6,3,0);potion("lucrum",GadEffects.LUCK.get(),4,6,5,1);potion("praecantatio",GadEffects.VIS_AFFINITY.get(),4,6,5,1);
        AuraEffectRegistry.register("vitreus",new PotionAura(GadEffects.ACHROMATIC.get(),4,6,6000,0){@Override public boolean accepts(Entity entity){return entity instanceof Player;}});
        AuraEffectRegistry.register("victus",new AuraEffect(){@Override public boolean accepts(Entity e){return e instanceof AgeableMob age&&age.isBaby();}@Override public void entity(ServerLevel level,BlockPos origin,Entity e){if(level.random.nextInt(20)==0)((AgeableMob)e).setAge(0);}});
        AuraEffectRegistry.register("pannus",new AuraEffect(){@Override public int interval(){return 10;}@Override public boolean accepts(Entity e){return e instanceof Sheep sheep&&sheep.isSheared();}@Override public void entity(ServerLevel level,BlockPos origin,Entity e){if(level.random.nextInt(10)==0)((Sheep)e).setSheared(false);}});
        AuraEffectRegistry.register("lux",new AuraEffect(){@Override public int interval(){return 4;}@Override public double range(){return 64;}@Override public boolean accepts(Entity entity){return true;}@Override public void entity(ServerLevel level,BlockPos origin,Entity entity){AuraSpawnProtection.touch(level,origin);}});
        AuraEffectRegistry.register("tempestas",new AuraEffect(){@Override public int blockCount(net.minecraft.util.RandomSource random){return random.nextInt(10)==0?1:0;}@Override public void block(ServerLevel level,BlockPos origin,BlockPos at){var lightning=EntityType.LIGHTNING_BOLT.create(level);if(lightning!=null){lightning.moveTo(at.getX()+.5,level.getHeight(net.minecraft.world.level.levelgen.Heightmap.Types.MOTION_BLOCKING,at.getX(),at.getZ()),at.getZ()+.5);level.addFreshEntity(lightning);}}});
        AuraEffectRegistry.register("vitium",new AuraEffect(){@Override public double range(){return 14;}@Override public boolean accepts(Entity e){return e instanceof LivingEntity;}@Override public void entity(ServerLevel level,BlockPos origin,Entity e){if(level.random.nextInt(20)==0&&!((LivingEntity)e).hasEffect(TCEffects.FLUX_TAINT.get()))((LivingEntity)e).addEffect(new MobEffectInstance(TCEffects.FLUX_TAINT.get(),400,0,true,false));}@Override public int blockCount(net.minecraft.util.RandomSource random){return 5;}@Override public void block(ServerLevel level,BlockPos origin,BlockPos at){if(!tc4revival.config.TCConfig.SERVER.generates(tc4revival.config.TCConfig.WorldFeature.TAINT))return;TaintFibreBlock.spread(level,at);if(level.random.nextInt(12)==0){WorldBiomeChanges.changeColumn(level,at,TCBiomes.TAINTED_LAND);level.blockEvent(at,level.getBlockState(at).getBlock(),1,0);}}});
        AuraEffectRegistry.register("gelum",new AuraEffect(){@Override public int interval(){return 2;}@Override public boolean accepts(Entity e){return e instanceof LivingEntity;}@Override public void entity(ServerLevel level,BlockPos origin,Entity e){extend((LivingEntity)e,MobEffects.MOVEMENT_SLOWDOWN,3600,5,1,true);}@Override public int blockCount(net.minecraft.util.RandomSource random){return random.nextInt(10)+10;}@Override public void block(ServerLevel level,BlockPos origin,BlockPos at){if(level.getBlockState(at).is(Blocks.WATER)&&level.getFluidState(at).isSource())level.setBlockAndUpdate(at,Blocks.ICE.defaultBlockState());}});
        AuraEffectRegistry.register("exanimis",new AuraEffect(){@Override public int interval(){return 4;}@Override public double range(){return 10;}@Override public boolean accepts(Entity e){return e instanceof LivingEntity living&&living.getMobType()==MobType.UNDEAD;}@Override public void entity(ServerLevel level,BlockPos origin,Entity e){extend((LivingEntity)e,MobEffects.DAMAGE_BOOST,3600,30,1,false);extend((LivingEntity)e,MobEffects.MOVEMENT_SPEED,3600,30,0,false);extend((LivingEntity)e,MobEffects.REGENERATION,3600,30,0,false);}@Override public int blockCount(net.minecraft.util.RandomSource random){return random.nextInt(60)==0?1:0;}@Override public void block(ServerLevel level,BlockPos origin,BlockPos at){var zombie=TCEntities.BRAINY_ZOMBIE.get().create(level);if(zombie!=null&&position(zombie,at,true)&&zombie.checkSpawnRules(level,MobSpawnType.NATURAL)&&level.noCollision(zombie)){land(zombie);level.addFreshEntity(zombie);}}});
        AuraEffectRegistry.register("auram",new AuraEffect(){@Override public int interval(){return 1;}@Override public boolean accepts(Entity e){return e instanceof Player;}@Override public void entity(ServerLevel level,BlockPos origin,Entity e){var stack=((Player)e).getMainHandItem();if(stack.getItem() instanceof CastingWandItem wand)for(var primal:tc4revival.aspect.TCAspects.catalog().primals())wand.receiveVis(stack,primal,4,false);}});
        AuraEffectRegistry.register("cognitio",new AuraEffect(){@Override public int interval(){return 40;}@Override public boolean accepts(Entity e){return e instanceof ServerPlayer;}@Override public void entity(ServerLevel level,BlockPos origin,Entity e){var player=(ServerPlayer)e;for(var primal:tc4revival.aspect.TCAspects.catalog().primals())if(level.random.nextInt(40)==0)tc4revival.research.KnowledgeSavedData.get(level.getServer()).update(player.getUUID(),level.random::nextInt,state->{state.discover(primal);state.changePool(primal,(short)1);if(level.random.nextInt(20)==0)state.changeWarp(tc4revival.research.PlayerKnowledge.WarpKind.TEMPORARY,1);return null;});}});
        AuraEffectRegistry.register("fabrico",new AuraEffect(){@Override public boolean accepts(Entity e){return e instanceof GolemEntity;}@Override public void entity(ServerLevel level,BlockPos origin,Entity e){extend((LivingEntity)e,GadEffects.GOLEM.get(),7200,10,0,false);}@Override public int blockCount(net.minecraft.util.RandomSource random){return net.minecraftforge.fml.ModList.get().isLoaded("automagy")?50:0;}@Override public void block(ServerLevel level,BlockPos origin,BlockPos at){AuraCompat.coolWorkbench(level,at);}});
        AuraEffectRegistry.register("herba",new Growth(1,180));AuraEffectRegistry.register("arbor",new Growth(3,120));
        AuraEffectRegistry.register("ignis",new AuraEffect(){@Override public boolean accepts(Entity e){return e instanceof LivingEntity;}@Override public void entity(ServerLevel level,BlockPos origin,Entity e){if(!e.fireImmune())e.setSecondsOnFire(10);}});
        AuraEffectRegistry.register("alienis",new AuraEffect(){@Override public int interval(){return 20;}@Override public boolean accepts(Entity e){return e instanceof Monster monster&&ChampionMobs.id(monster)<0&&monster.getAttributeValue(net.minecraft.world.entity.ai.attributes.Attributes.MAX_HEALTH)>=10&&championAllowed(monster);}@Override public void entity(ServerLevel level,BlockPos origin,Entity e){if(level.random.nextInt(4)!=0)return;var monster=(Monster)e;var effect=monster.getEffect(GadEffects.ELDRITCH.get());if(effect!=null&&effect.getAmplifier()>4){ChampionMobs.make(monster,false);monster.removeEffect(GadEffects.ELDRITCH.get());}else monster.addEffect(new MobEffectInstance(GadEffects.ELDRITCH.get(),1200,effect==null?1:effect.getAmplifier()+1));}});
        AuraEffectRegistry.register("spiritus",new SpawnAura(60){@Override protected Mob create(ServerLevel level){return level.random.nextBoolean()?EntityType.SKELETON.create(level):EntityType.ZOMBIE.create(level);}@Override protected boolean prepare(Mob mob){if(mob.level().getDifficulty()==net.minecraft.world.Difficulty.PEACEFUL)return false;return soulEquipment(mob);}});
        AuraEffectRegistry.register("limus",new SpawnAura(40){@Override protected Mob create(ServerLevel level){var slime=EntityType.SLIME.create(level);if(slime!=null)slime.setSize(1,true);return slime;}@Override protected boolean prepare(Mob mob){return mob.level().getDifficulty()!=net.minecraft.world.Difficulty.PEACEFUL;}});
        AuraEffectRegistry.register("bestia",new SpawnAura(60){@Override protected Mob create(ServerLevel level){var types=java.util.List.of(EntityType.SHEEP,EntityType.COW,EntityType.CHICKEN,EntityType.PIG);return types.get(level.random.nextInt(types.size())).create(level);}});
    }
    public static void extend(LivingEntity entity,MobEffect effect,int cap,int duration,int amplifier,boolean ambient){var active=entity.getEffect(effect);int current=active==null?0:active.getDuration();if(cap-current>=duration)entity.addEffect(new MobEffectInstance(effect,current+duration,amplifier,ambient,true));}
    protected static void potion(String aspect,MobEffect effect,int interval,int duration,int minutes,int amplifier){AuraEffectRegistry.register(aspect,new PotionAura(effect,interval,duration,minutes*1200,amplifier));}
    public static class PotionAura extends AuraEffect {
        public final MobEffect potion;public final int interval,added,cap,amplifier;
        public PotionAura(MobEffect potion,int interval,int added,int cap,int amplifier){this.potion=potion;this.interval=interval;this.added=added;this.cap=cap;this.amplifier=amplifier;}
        @Override public int interval(){return interval;}@Override public boolean accepts(Entity e){return e instanceof LivingEntity;}@Override public void entity(ServerLevel level,BlockPos origin,Entity e){extend((LivingEntity)e,potion,cap,added,amplifier,true);}
    }
    public static class Growth extends AuraEffect {
        protected final int delay,count;public Growth(int delay,int count){this.delay=delay;this.count=count;}
        @Override public int interval(){return delay;}@Override public int blockCount(net.minecraft.util.RandomSource random){return count;}
        @Override public void block(ServerLevel level,BlockPos origin,BlockPos chosen){var state=level.getBlockState(chosen);if(state.isRandomlyTicking())AuraGrowthQueue.schedule(level,chosen,level.random.nextInt(8)+2);AuraCompat.growCrop(level,chosen);}
    }
    public static class SpawnAura extends AuraEffect {
        protected final int chance;public SpawnAura(int chance){this.chance=chance;}@Override public int interval(){return 4;}@Override public int blockCount(net.minecraft.util.RandomSource random){return random.nextInt(chance)==0?1:0;}
        protected Mob create(ServerLevel level){return null;}protected boolean prepare(Mob mob){return true;}
        @Override public void block(ServerLevel level,BlockPos origin,BlockPos chosen){var mob=create(level);if(mob!=null&&position(mob,chosen,true)&&prepare(mob)){land(mob);level.addFreshEntity(mob);}}
    }
    public static boolean position(Mob mob,BlockPos at,boolean vary){var world=mob.level();if(!world.hasChunkAt(at)||at.getY()<world.getMinBuildHeight()+1||at.getY()>=world.getMaxBuildHeight()-1)return false;if(!world.isEmptyBlock(at))return vary&&(position(mob,at.above(),false)||position(mob,at.below(),false));if(world.isEmptyBlock(at.above())){mob.setPos(at.getX(),at.getY()+1,at.getZ());return true;}if(world.isEmptyBlock(at.below())){mob.setPos(at.getX(),at.getY()-1,at.getZ());return true;}return vary&&(position(mob,at.east(),false)||position(mob,at.south(),false)||position(mob,at.west(),false)||position(mob,at.north(),false));}
    public static void land(Mob mob){var pos=mob.blockPosition();while(pos.getY()>mob.level().getMinBuildHeight()&&mob.level().isEmptyBlock(pos))pos=pos.below();pos=pos.above();mob.setPos(pos.getX()+.5,pos.getY(),pos.getZ()+.5);}
    protected static boolean championAllowed(Monster mob){var id=net.minecraftforge.registries.ForgeRegistries.ENTITY_TYPES.getKey(mob.getType());if(id==null)return false;if(id.getNamespace().equals("minecraft"))return java.util.Set.of("zombie","zombified_piglin","spider","cave_spider","blaze","enderman","skeleton","wither_skeleton","witch").contains(id.getPath());return mob instanceof ThaumcraftBossEntity||mob instanceof CultistEntity||id.getNamespace().equals("thaumcraft")&&java.util.Set.of("eldritch_crab","brainy_zombie","giant_brainy_zombie","taint_spider","taintacle","taintacle_small","taintacle_giant","watcher","wisp","pech","inhabited_zombie").contains(id.getPath());}
    protected static boolean soulEquipment(Mob mob){Item[][] equipment={{Items.BOW,Items.WOODEN_SWORD,Items.STONE_SWORD,Items.IRON_SWORD,Items.STONE_AXE,Items.IRON_AXE},{Items.LEATHER_BOOTS,Items.CHAINMAIL_BOOTS,Items.IRON_BOOTS},{Items.LEATHER_LEGGINGS,Items.CHAINMAIL_LEGGINGS,Items.IRON_LEGGINGS},{Items.LEATHER_CHESTPLATE,Items.CHAINMAIL_CHESTPLATE,Items.IRON_CHESTPLATE},{Items.CARVED_PUMPKIN,Items.JACK_O_LANTERN}};EquipmentSlot[] slots={EquipmentSlot.MAINHAND,EquipmentSlot.FEET,EquipmentSlot.LEGS,EquipmentSlot.CHEST,EquipmentSlot.HEAD};for(var slot:EquipmentSlot.values())mob.setItemSlot(slot,ItemStack.EMPTY);int remaining=(mob.getRandom().nextInt(3)==0?1:0)+2,attempts=40;while(remaining>0&&attempts-->0){int index=mob.getMainHandItem().isEmpty()?0:mob.getItemBySlot(EquipmentSlot.HEAD).isEmpty()?4:mob.getRandom().nextInt(3)+1;if(!mob.getItemBySlot(slots[index]).isEmpty())continue;var choices=equipment[index];var item=choices[mob.getRandom().nextInt(choices.length)];if(item==Items.BOW&&!(mob instanceof Skeleton))continue;mob.setItemSlot(slots[index],new ItemStack(item));mob.setDropChance(slots[index],0);remaining--;}if(remaining>0)return false;mob.addEffect(new MobEffectInstance(MobEffects.INVISIBILITY,630720000,1,true,true));return true;}
}
